-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — POLSKO (10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Kladská kotlina a Stolové hory
  delete from public.routes where name = 'Kladská kotlina a Stolové hory' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kladská kotlina a Stolové hory', 'Okruh nejkrásnějšími silnicemi Kladské kotliny hned za českou hranicí. Serpentiny přes Stolové hory, lázeňská městečka a mohutná pevnost Kłodzko střídají svižné úseky mezi Dušníky a Bystřicí. Nejlepší od května do října; pozor na úzké horské okresky, turisty a rychle se měnící počasí v hřebenech.', 'loop', 185, 270, 'medium',
     '[{"lat": 50.4344, "lng": 16.6619, "label": "Start: Kłodzko"}, {"lat": 50.4056, "lng": 16.3706, "label": "Duszniki-Zdrój"}, {"lat": 50.4433, "lng": 16.2469, "label": "Kudowa-Zdrój"}, {"lat": 50.4744, "lng": 16.3372, "label": "Stolové hory – Szczeliniec"}, {"lat": 50.3061, "lng": 16.6486, "label": "Bystrzyca Kłodzka"}, {"lat": 50.4344, "lng": 16.6619, "label": "Cíl: Kłodzko"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.4344,16.6619&destination=50.4344,16.6619&travelmode=driving&waypoints=50.4056,16.3706%7C50.4433,16.2469%7C50.4744,16.3372%7C50.3061,16.6486', 'https://commons.wikimedia.org/wiki/Special:FilePath/Twierdza_K%C5%82odzka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Twierdza_K%C5%82odzka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Duszniki-Zdr%C3%B3j_-_rynek.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Wielki.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kudowa-Zdr%C3%B3j_-_park_zdrojowy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bystrzyca_K%C5%82odzka_-_panorama.jpg"}'::text[], '{"Pevnost Kłodzko","Duszniki-Zdrój","Szczeliniec Wielki","Kudowa-Zdrój","Bystrzyca Kłodzka"}'::text[], '{"PL"}'::text[], false, 4710, 'approved');

  -- Krkonoše z polské strany
  delete from public.routes where name = 'Krkonoše z polské strany' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Krkonoše z polské strany', 'Vyjížďka pod nejvyššími vrcholy Krkonoš na polské straně hor. Karpacz se Sněžkou, Szklarska Poręba a vodopád Kamieńczyka nabízí táhlé zatáčky lesními úseky. Nejlepší v létě; pozor na dřevo a listí v zatáčkách a na horský provoz o víkendech.', 'loop', 150, 225, 'medium',
     '[{"lat": 50.9033, "lng": 15.7367, "label": "Start: Jelenia Góra"}, {"lat": 50.7803, "lng": 15.7519, "label": "Karpacz"}, {"lat": 50.8272, "lng": 15.5219, "label": "Szklarska Poręba"}, {"lat": 50.8072, "lng": 15.51, "label": "Vodopád Kamieńczyk"}, {"lat": 50.8494, "lng": 15.7106, "label": "Zámek Chojnik"}, {"lat": 50.9033, "lng": 15.7367, "label": "Cíl: Jelenia Góra"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.9033,15.7367&destination=50.9033,15.7367&travelmode=driving&waypoints=50.7803,15.7519%7C50.8272,15.5219%7C50.8072,15.51%7C50.8494,15.7106', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82_Wang_w_Karpaczu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82_Wang_w_Karpaczu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szklarska_Por%C4%99ba.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wodospad_Kamie%C5%84czyka.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Chojnik.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia_G%C3%B3ra_-_rynek.jpg"}'::text[], '{"Karpacz a kostel Wang","Szklarska Poręba","Vodopád Kamieńczyk","Zámek Chojnik","Jelenia Góra – náměstí"}'::text[], '{"PL"}'::text[], false, 4720, 'approved');

  -- Bieszczady – Velký okruh
  delete from public.routes where name = 'Bieszczady – Velký okruh' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Bieszczady – Velký okruh', 'Legendární Velká bieszczadská obwodnica nejdivočejším koutem Polska. Prázdné silnice, horské průsmyky a poloniny táhnoucí se k obzoru, mezi tím dřevěné cerkve a stáda. Nejlepší od června do září; pozor na dobytek na silnici, řídké čerpací stanice a mlhy v sedlech.', 'loop', 175, 240, 'medium',
     '[{"lat": 49.4703, "lng": 22.3306, "label": "Start: Lesko"}, {"lat": 49.4033, "lng": 22.4589, "label": "Solina – přehrada"}, {"lat": 49.1611, "lng": 22.5158, "label": "Wetlina"}, {"lat": 49.1, "lng": 22.6906, "label": "Ustrzyki Górne"}, {"lat": 49.2003, "lng": 22.7189, "label": "Smolnik"}, {"lat": 49.4703, "lng": 22.3306, "label": "Cíl: Lesko"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.4703,22.3306&destination=49.4703,22.3306&travelmode=driving&waypoints=49.4033,22.4589%7C49.1611,22.5158%7C49.1,22.6906%7C49.2003,22.7189', 'https://commons.wikimedia.org/wiki/Special:FilePath/Zapora_Soli%C5%84ska.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zapora_Soli%C5%84ska.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ustrzyki_G%C3%B3rne.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wetlina.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cerkiew_w_Smolniku.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lesko_synagoga.jpg"}'::text[], '{"Přehrada Solina","Ustrzyki Górne","Wetlina","Cerkev v Smolniku","Lesko – synagoga a zámek"}'::text[], '{"PL"}'::text[], false, 4730, 'approved');

  -- Pieniny a průlom Dunajce
  delete from public.routes where name = 'Pieniny a průlom Dunajce' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Pieniny a průlom Dunajce', 'Okruh kolem malebného pohoří Pieniny na slovenské hranici. Serpentiny nad průlomem Dunajce, pohádkový hrad Niedzica nad jezerem a lázeňská Szczawnica lákají na svižnou i pohodovou jízdu. Nejlepší od jara do podzimu; pozor na turistický provoz a úzké silnice u přehrady.', 'loop', 140, 210, 'medium',
     '[{"lat": 49.4772, "lng": 20.0322, "label": "Start: Nowy Targ"}, {"lat": 49.4189, "lng": 20.4189, "label": "Krościenko"}, {"lat": 49.4269, "lng": 20.4842, "label": "Szczawnica"}, {"lat": 49.4189, "lng": 20.3053, "label": "Niedzica"}, {"lat": 49.4383, "lng": 20.31, "label": "Czorsztyn"}, {"lat": 49.4772, "lng": 20.0322, "label": "Cíl: Nowy Targ"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.4772,20.0322&destination=49.4772,20.0322&travelmode=driving&waypoints=49.4189,20.4189%7C49.4269,20.4842%7C49.4189,20.3053%7C49.4383,20.31', 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Niedzicy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Niedzicy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szczawnica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Czorsztyn.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Prze%C5%82om_Dunajca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Nowy_Targ_rynek.jpg"}'::text[], '{"Hrad Niedzica","Szczawnica","Zřícenina Czorsztyn","Průlom Dunajce","Nowy Targ"}'::text[], '{"PL"}'::text[], false, 4740, 'approved');

  -- Mazurská velká jezera
  delete from public.routes where name = 'Mazurská velká jezera' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Mazurská velká jezera', 'Pohodový okruh krajem tisíce jezer na severovýchodě Polska. Táhlé silnice mezi hladinami, zvedací most v Giżycku, poutní Svatá Lipka a Vlčí doupě spojují klidnou jízdu s historií. Nejlepší od května do září; pozor na turisty v přístavech a přejezdy přes mosty.', 'loop', 210, 270, 'easy',
     '[{"lat": 54.0378, "lng": 21.7644, "label": "Start: Giżycko"}, {"lat": 53.8025, "lng": 21.5789, "label": "Mikołajki"}, {"lat": 53.9375, "lng": 21.5464, "label": "Ryn"}, {"lat": 54.0983, "lng": 21.4972, "label": "Święta Lipka"}, {"lat": 54.0803, "lng": 21.4939, "label": "Wilczy Szaniec"}, {"lat": 54.0378, "lng": 21.7644, "label": "Cíl: Giżycko"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.0378,21.7644&destination=54.0378,21.7644&travelmode=driving&waypoints=53.8025,21.5789%7C53.9375,21.5464%7C54.0983,21.4972%7C54.0803,21.4939', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kanal_Gi%C5%BCycki_i_most_obrotowy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kanal_Gi%C5%BCycki_i_most_obrotowy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Ryn_(3).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Miko%C5%82ajki_miasto.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/POL_Swieta_Lipka_001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Poland._K%C4%99trzyn._Gier%C5%82o%C5%BC._Wolf%27s_Lair_009.JPG"}'::text[], '{"Giżycko a zvedací most","Zámek Ryn","Mikołajki","Poutní bazilika Święta Lipka","Vlčí doupě (Wilczy Szaniec)"}'::text[], '{"PL"}'::text[], false, 4750, 'approved');

  -- Kašubské Švýcarsko
  delete from public.routes where name = 'Kašubské Švýcarsko' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Kašubské Švýcarsko', 'Okruh zvlněnou krajinou Kašub jižně od Gdaňsku, mezi jezery a lesnatými kopci. Nejvyšší vrch nížinného Polska Wieżyca, převrácený dům v Szymbarku a klidné okresky dělají z regionu příjemnou vyjížďku. Nejlepší od jara do podzimu; pozor na úzké silnice mezi jezery.', 'loop', 160, 225, 'medium',
     '[{"lat": 54.3324, "lng": 18.1994, "label": "Start: Kartuzy"}, {"lat": 54.2158, "lng": 18.0308, "label": "Chmielno"}, {"lat": 54.2317, "lng": 18.1, "label": "Wieżyca"}, {"lat": 54.1247, "lng": 18.0308, "label": "Szymbark"}, {"lat": 54.1219, "lng": 17.9772, "label": "Kościerzyna"}, {"lat": 54.3324, "lng": 18.1994, "label": "Cíl: Kartuzy"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.3324,18.1994&destination=54.3324,18.1994&travelmode=driving&waypoints=54.2158,18.0308%7C54.2317,18.1%7C54.1247,18.0308%7C54.1219,17.9772', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kartuzy_kolegiata.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kartuzy_kolegiata.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Chmielno_Biale_Jezioro_1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wie%C5%BCyca_(Ni%C5%BC_Polski)-wieza_widokowa.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Szymbark_(Szimbark)%2C_Dom_do_g%C3%B3ry_nogami_-_fotopolska.eu_(180802).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bcierzyna_Rynek.jpg"}'::text[], '{"Kartuzy – kolegiáta","Chmielno a Bílé jezero","Wieżyca – rozhledna","Převrácený dům v Szymbarku","Kościerzyna – náměstí"}'::text[], '{"PL"}'::text[], false, 4760, 'approved');

  -- Trójmiasto a poloostrov Hel
  delete from public.routes where name = 'Trójmiasto a poloostrov Hel' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Trójmiasto a poloostrov Hel', 'Pobřežní trasa od hanzovního Gdaňsku přes lázeňský Sopot až na špičku poloostrova Hel. Historické centrum, molo do moře a rovná silnice mezi dunami a plážemi. Nejlepší v létě; pozor na hustý provoz v sezoně a na omezení na úzkém poloostrově.', 'poi', 130, 195, 'easy',
     '[{"lat": 54.348, "lng": 18.6533, "label": "Start: Gdańsk"}, {"lat": 54.4483, "lng": 18.5697, "label": "Sopot – molo"}, {"lat": 54.5189, "lng": 18.5514, "label": "Gdynia"}, {"lat": 54.698, "lng": 18.69, "label": "Jastarnia"}, {"lat": 54.6083, "lng": 18.8036, "label": "Hel"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.348,18.6533&destination=54.6083,18.8036&travelmode=driving&waypoints=54.4483,18.5697%7C54.5189,18.5514%7C54.698,18.69', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gda%C5%84sk%2C_D%C5%82ugi_Targ_(HB1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gda%C5%84sk%2C_D%C5%82ugi_Targ_(HB1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sopot_Molo_and_main_square_2024_aerial.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dar_Pomorza%2C_Gdynia%2C_20090705%2C_1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jastarnia%2C_port_rybacki.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Latarnia_morska_hel_lighthouse_poland.JPG"}'::text[], '{"Gdańsk – Długi Targ","Sopot – molo","Gdynia – Dar Pomorza","Jastarnia – rybářský přístav","Hel – maják a fokarium"}'::text[], '{"PL"}'::text[], false, 4770, 'approved');

  -- Orlí hnízda – Jura Krakowsko-Częstochowska
  delete from public.routes where name = 'Orlí hnízda – Jura Krakowsko-Częstochowska' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Orlí hnízda – Jura Krakowsko-Częstochowska', 'Trasa Orlích hnízd po vápencové Juře mezi Krakovem a Čenstochovou. Skalní hrady na bílých útesech, jeskyně a poutní Jasná Hora tvoří jednu z nejromantičtějších tras Polska. Nejlepší od jara do podzimu; pozor na turisty u hradů a úzké silnice mezi skalami.', 'loop', 170, 240, 'medium',
     '[{"lat": 50.8118, "lng": 19.1203, "label": "Start: Częstochowa"}, {"lat": 50.672, "lng": 19.4472, "label": "Olsztyn"}, {"lat": 50.612, "lng": 19.5344, "label": "Mirów"}, {"lat": 50.6089, "lng": 19.5464, "label": "Bobolice"}, {"lat": 50.4517, "lng": 19.5525, "label": "Ogrodzieniec"}, {"lat": 50.8118, "lng": 19.1203, "label": "Cíl: Częstochowa"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.8118,19.1203&destination=50.8118,19.1203&travelmode=driving&waypoints=50.672,19.4472%7C50.612,19.5344%7C50.6089,19.5464%7C50.4517,19.5525', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cz%C4%99stochowa_-_Aleja_Naj%C5%9Bwi%C4%99tszej_Maryi_Panny.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cz%C4%99stochowa_-_Aleja_Naj%C5%9Bwi%C4%99tszej_Maryi_Panny.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Olsztynie_po%C5%82o%C5%BCony_w_wojew%C3%B3dztwie_%C5%9Bl%C4%85skim%2C_w_powiecie_cz%C4%99stochowskim%2C_w_gminie_Olsztyn._08.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Mirowie-Castle_in_Mirow_-_panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bobolice_Castle_at_sunset.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Ogrodzieniec_w_Podzamczu.jpg"}'::text[], '{"Jasná Hora v Čenstochové","Hrad Olsztyn","Hrad Mirów","Hrad Bobolice","Hrad Ogrodzieniec"}'::text[], '{"PL"}'::text[], false, 4780, 'approved');

  -- Svatokřížské hory
  delete from public.routes where name = 'Svatokřížské hory' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Svatokřížské hory', 'Okruh nejstaršími horami Polska ve Svatokřížském kraji. Klášter na Svatém Kříži, jeskyně Raj a královský hrad v Chęcinach střídají lesní hřebeny Svatokřížského pralesa. Nejlepší od jara do podzimu; pozor na lesní úseky a turistický ruch u památek.', 'loop', 165, 225, 'medium',
     '[{"lat": 50.8661, "lng": 20.6286, "label": "Start: Kielce"}, {"lat": 50.7975, "lng": 20.4667, "label": "Chęciny"}, {"lat": 50.8203, "lng": 20.43, "label": "Jeskyně Raj"}, {"lat": 50.86, "lng": 21.05, "label": "Svatý Kříž"}, {"lat": 50.8661, "lng": 20.6286, "label": "Cíl: Kielce"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.8661,20.6286&destination=50.8661,20.6286&travelmode=driving&waypoints=50.7975,20.4667%7C50.8203,20.43%7C50.86,21.05', 'https://commons.wikimedia.org/wiki/Special:FilePath/20130421_Kielce_Palac_Biskupow_Krakowskich_3127.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/20130421_Kielce_Palac_Biskupow_Krakowskich_3127.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C4%99ciny_Castle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Jaskinia_Raj.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Swiety_Krzyz_klasztor_3963_20080703.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kadzielnia_w_Kielcach.jpg"}'::text[], '{"Kielce – Biskupský palác","Hrad Chęciny","Jeskyně Raj","Klášter na Svatém Kříži","Kadzielnia"}'::text[], '{"PL"}'::text[], false, 4790, 'approved');

  -- Roztocze a renesanční Zamość
  delete from public.routes where name = 'Roztocze a renesanční Zamość' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Roztocze a renesanční Zamość', 'Klidná trasa jihovýchodním pomezím Polska přes zvlněné Roztocze. Ideální renesanční město Zamość, národní park a poutní Krasnobród nabízí pohodovou jízdu prázdnými silnicemi. Nejlepší od jara do podzimu; pozor na zemědělskou techniku a řidší zázemí.', 'loop', 180, 240, 'easy',
