  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pevnost Kłodzko', 'Mohutná barokní pevnost nad městem s labyrintem podzemních chodeb a výhledem na celou kotlinu. Jedna z nejzachovalejších fortifikací v Polsku.', 50.4361, 16.6572, 'https://commons.wikimedia.org/wiki/Special:FilePath/Twierdza_K%C5%82odzka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Twierdza_K%C5%82odzka.jpg"}'::text[], 0),
    (v_route, 'Duszniki-Zdrój', 'Půvabné lázeňské město s historickou papírnou a každoročním Chopinovým festivalem. Ideální zastávka na kávu na náměstí.', 50.4056, 16.3706, 'https://commons.wikimedia.org/wiki/Special:FilePath/Duszniki-Zdr%C3%B3j_-_rynek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Duszniki-Zdr%C3%B3j_-_rynek.jpg"}'::text[], 1),
    (v_route, 'Szczeliniec Wielki', 'Nejvyšší vrchol Stolových hor s bizarními skalními útvary a vyhlídkami do kraje. K parkovišti pod vrcholem vede pěkná horská silnice.', 50.4744, 16.3372, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Wielki.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szczeliniec_Wielki.jpg"}'::text[], 2),
    (v_route, 'Kudowa-Zdrój', 'Příhraniční lázeňské městečko s parkem a nedalekou kaplí lebek v Czermné. Klidná zastávka kousek od hranice.', 50.4433, 16.2469, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kudowa-Zdr%C3%B3j_-_park_zdrojowy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kudowa-Zdr%C3%B3j_-_park_zdrojowy.jpg"}'::text[], 3),
    (v_route, 'Bystrzyca Kłodzka', 'Historické město na ostrohu nad řekou Nysou s dochovanými hradbami a muzeem sirek. Malebné uličky staré zástavby.', 50.3061, 16.6486, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bystrzyca_K%C5%82odzka_-_panorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bystrzyca_K%C5%82odzka_-_panorama.jpg"}'::text[], 4);
  insert into public.routes
