  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Karpacz a kostel Wang', 'Horské středisko pod Sněžkou se středověkým dřevěným kostelem Wang přeneseným až z Norska. Výchozí bod k nejvyššímu vrcholu Krkonoš.', 50.7803, 15.7519, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82_Wang_w_Karpaczu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bci%C3%B3%C5%82_Wang_w_Karpaczu.jpg"}'::text[], 0),
    (v_route, 'Szklarska Poręba', 'Oblíbené středisko na západě Krkonoš, brána k vodopádům a hřebenům. Pěkné náměstí a spousta občerstvení.', 50.8272, 15.5219, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szklarska_Por%C4%99ba.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szklarska_Por%C4%99ba.jpg"}'::text[], 1),
    (v_route, 'Vodopád Kamieńczyk', 'Nejvyšší krkonošský vodopád (27 m) padající do úzké skalní rokle. Krátká procházka od parkoviště lesem.', 50.8072, 15.51, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wodospad_Kamie%C5%84czyka.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wodospad_Kamie%C5%84czyka.jpg"}'::text[], 2),
    (v_route, 'Zámek Chojnik', 'Zřícenina gotického hradu na strmém ostrohu s dalekým výhledem do Jelenohorské kotliny. Romantická zastávka nad lesy.', 50.8494, 15.7106, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Chojnik.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Chojnik.jpg"}'::text[], 3),
    (v_route, 'Jelenia Góra – náměstí', 'Historické centrum s podloubím a barevnými měšťanskými domy. Ideální na oběd před nebo po okruhu.', 50.9033, 15.7367, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia_G%C3%B3ra_-_rynek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jelenia_G%C3%B3ra_-_rynek.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Přehrada Solina', 'Největší vodní nádrž v Polsku s impozantní hrází a jezerem mezi zalesněnými kopci. Oblíbené místo na projížďku lodí i fotky.', 49.4033, 22.4589, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zapora_Soli%C5%84ska.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zapora_Soli%C5%84ska.jpg"}'::text[], 0),
    (v_route, 'Ustrzyki Górne', 'Horská osada v srdci Bieszczad, výchozí bod na poloniny. Poslední civilizace před nejdivočejšími hřebeny.', 49.1, 22.6906, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ustrzyki_G%C3%B3rne.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ustrzyki_G%C3%B3rne.jpg"}'::text[], 1),
    (v_route, 'Wetlina', 'Osada v údolí obklopená polodivokými kopci, oblíbená mezi motorkáři a trampy. Skvělé místo na svařák a klid.', 49.1611, 22.5158, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wetlina.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wetlina.jpg"}'::text[], 2),
    (v_route, 'Cerkev v Smolniku', 'Dřevěná řeckokatolická cerkev zapsaná na seznam UNESCO, památka po zdejších Bojcích. Ukázka mizející kultury Bieszczad.', 49.2003, 22.7189, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cerkiew_w_Smolniku.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cerkiew_w_Smolniku.jpg"}'::text[], 3),
    (v_route, 'Lesko – synagoga a zámek', 'Bývalé pohraniční městečko s renesanční synagogou a zámkem Kmitů. Brána do Bieszczad s dobrým zázemím.', 49.4703, 22.3306, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lesko_synagoga.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lesko_synagoga.jpg"}'::text[], 4);
  insert into public.routes
