  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Hrad Niedzica', 'Pohádkový gotický hrad Dunajec nad Czorsztyńským jezerem, opředený legendami o inckém pokladu. Jeden z nejfotogeničtějších hradů v Polsku.', 49.4189, 20.3053, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Niedzicy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Niedzicy.jpg"}'::text[], 0),
    (v_route, 'Szczawnica', 'Půvabné lázeňské městečko na úpatí Pienin, cíl splavů Dunajce na dřevěných vorech. Příjemná promenáda a zázemí.', 49.4269, 20.4842, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szczawnica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szczawnica.jpg"}'::text[], 1),
    (v_route, 'Zřícenina Czorsztyn', 'Zřícenina královského hradu na protějším břehu jezera naproti Niedzici. Krásný výhled na vodní hladinu a Pieniny.', 49.4383, 20.31, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Czorsztyn.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Czorsztyn.jpg"}'::text[], 2),
    (v_route, 'Průlom Dunajce', 'Dramatický kaňon, kterým se řeka prořezává mezi vápencovými štíty Pienin. Ikonická scenérie polsko-slovenského pomezí.', 49.4064, 20.42, 'https://commons.wikimedia.org/wiki/Special:FilePath/Prze%C5%82om_Dunajca.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Prze%C5%82om_Dunajca.jpg"}'::text[], 3),
    (v_route, 'Nowy Targ', 'Hlavní město Podhalí s velkým náměstím a výhledy na Tatry. Dobré zázemí a brána do polských hor.', 49.4772, 20.0322, 'https://commons.wikimedia.org/wiki/Special:FilePath/Nowy_Targ_rynek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Nowy_Targ_rynek.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Giżycko a zvedací most', 'Přístavní město mezi jezery Niegocin a Kisajno s unikátním otočným mostem přes Luczański kanál. Srdce mazurského jachtingu.', 54.0378, 21.7644, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kanal_Gi%C5%BCycki_i_most_obrotowy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kanal_Gi%C5%BCycki_i_most_obrotowy.jpg"}'::text[], 0),
    (v_route, 'Zámek Ryn', 'Mohutný cihlový hrad Německých rytířů nad jezerem Ryńskie, dnes hotel. Dominanta městečka a pěkný výhled na vodu.', 53.9375, 21.5464, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Ryn_(3).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Ryn_(3).jpg"}'::text[], 1),
    (v_route, 'Mikołajki', 'Půvabné přístavní městečko zvané perla Mazur, plné jachet a kaváren u vody. Živá zastávka na oběd.', 53.8025, 21.5789, 'https://commons.wikimedia.org/wiki/Special:FilePath/Miko%C5%82ajki_miasto.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Miko%C5%82ajki_miasto.jpg"}'::text[], 2),
    (v_route, 'Poutní bazilika Święta Lipka', 'Skvostná barokní poutní bazilika s proslulými varhanami s pohyblivými figurami. Jeden z nejkrásnějších kostelů severu.', 54.0983, 21.4972, 'https://commons.wikimedia.org/wiki/Special:FilePath/POL_Swieta_Lipka_001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/POL_Swieta_Lipka_001.jpg"}'::text[], 3),
    (v_route, 'Vlčí doupě (Wilczy Szaniec)', 'Rozsáhlé ruiny Hitlerova hlavního stanu ukryté v lesích u Kętrzynu, dějiště atentátu z roku 1944. Působivá vojenská památka.', 54.0803, 21.4939, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poland._K%C4%99trzyn._Gier%C5%82o%C5%BC._Wolf%27s_Lair_009.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poland._K%C4%99trzyn._Gier%C5%82o%C5%BC._Wolf%27s_Lair_009.JPG"}'::text[], 4);
  insert into public.routes
