  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kartuzy – kolegiáta', 'Kartuziánský klášterní kostel se střechou ve tvaru rakve, symbol pomíjivosti. Centrum kašubské kultury.', 54.3324, 18.1994, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kartuzy_kolegiata.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kartuzy_kolegiata.jpg"}'::text[], 0),
    (v_route, 'Chmielno a Bílé jezero', 'Vesnice mezi jezery proslulá keramickou dílnou Neclů. Klidné místo na koupání a odpočinek u vody.', 54.2158, 18.0308, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chmielno_Biale_Jezioro_1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chmielno_Biale_Jezioro_1.jpg"}'::text[], 1),
    (v_route, 'Wieżyca – rozhledna', 'Nejvyšší vrchol Kašub a celé severopolské nížiny (329 m) s vyhlídkovou věží nad lesy. Pěkný rozhled po jezerní pahorkatině.', 54.2317, 18.1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wie%C5%BCyca_(Ni%C5%BC_Polski)-wieza_widokowa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wie%C5%BCyca_(Ni%C5%BC_Polski)-wieza_widokowa.jpg"}'::text[], 2),
    (v_route, 'Převrácený dům v Szymbarku', 'Slavný dům postavený vzhůru nohama ve skanzenu, oblíbená turistická atrakce. Zábavná zastávka pro každého.', 54.1247, 18.0308, 'https://commons.wikimedia.org/wiki/Special:FilePath/Szymbark_(Szimbark)%2C_Dom_do_g%C3%B3ry_nogami_-_fotopolska.eu_(180802).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Szymbark_(Szimbark)%2C_Dom_do_g%C3%B3ry_nogami_-_fotopolska.eu_(180802).jpg"}'::text[], 3),
    (v_route, 'Kościerzyna – náměstí', 'Kašubské městečko s pěkným náměstím a muzeem železnice. Dobré zázemí uprostřed okruhu.', 54.1219, 17.9772, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bcierzyna_Rynek.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ko%C5%9Bcierzyna_Rynek.jpg"}'::text[], 4);
  insert into public.routes
