  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Gdańsk – Długi Targ', 'Nádherné hanzovní centrum s Dlouhým trhem, Neptunovou fontánou a Mariánskou bránou. Jedno z nejkrásnějších měst u Baltu.', 54.3489, 18.6533, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gda%C5%84sk%2C_D%C5%82ugi_Targ_(HB1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gda%C5%84sk%2C_D%C5%82ugi_Targ_(HB1).jpg"}'::text[], 0),
    (v_route, 'Sopot – molo', 'Nejdelší dřevěné molo v Evropě zasahující daleko do Baltu, srdce lázeňského Sopotu. Živá promenáda a pláže.', 54.4483, 18.5697, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sopot_Molo_and_main_square_2024_aerial.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sopot_Molo_and_main_square_2024_aerial.jpg"}'::text[], 1),
    (v_route, 'Gdynia – Dar Pomorza', 'Moderní přístavní město s historickou plachetnicí Dar Pomorza kotvící na nábřeží. Přímořská atmosféra a muzea.', 54.5189, 18.5514, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dar_Pomorza%2C_Gdynia%2C_20090705%2C_1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dar_Pomorza%2C_Gdynia%2C_20090705%2C_1.jpg"}'::text[], 2),
    (v_route, 'Jastarnia – rybářský přístav', 'Klidné letovisko uprostřed poloostrova Hel s rybářským přístavem a plážemi z obou stran. Zastávka na čerstvé ryby.', 54.698, 18.69, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jastarnia%2C_port_rybacki.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jastarnia%2C_port_rybacki.jpg"}'::text[], 3),
    (v_route, 'Hel – maják a fokarium', 'Cíp poloostrova s majákem, muzeem rybolovu a fokáriem s tuleni. Konec cesty s výhledem na moře ze všech stran.', 54.6083, 18.8036, 'https://commons.wikimedia.org/wiki/Special:FilePath/Latarnia_morska_hel_lighthouse_poland.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Latarnia_morska_hel_lighthouse_poland.JPG"}'::text[], 4);
  insert into public.routes
