  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Jasná Hora v Čenstochové', 'Nejvýznamnější polské poutní místo s obrazem Černé Madony a mohutným klášterem. Duchovní srdce Polska.', 50.8125, 19.0967, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cz%C4%99stochowa_-_Aleja_Naj%C5%9Bwi%C4%99tszej_Maryi_Panny.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cz%C4%99stochowa_-_Aleja_Naj%C5%9Bwi%C4%99tszej_Maryi_Panny.JPG"}'::text[], 0),
    (v_route, 'Hrad Olsztyn', 'Malebná zřícenina královského hradu na vápencových skalách nedaleko Čenstochové. První z Orlích hnízd na trase.', 50.672, 19.4472, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Olsztynie_po%C5%82o%C5%BCony_w_wojew%C3%B3dztwie_%C5%9Bl%C4%85skim%2C_w_powiecie_cz%C4%99stochowskim%2C_w_gminie_Olsztyn._08.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Olsztynie_po%C5%82o%C5%BCony_w_wojew%C3%B3dztwie_%C5%9Bl%C4%85skim%2C_w_powiecie_cz%C4%99stochowskim%2C_w_gminie_Olsztyn._08.JPG"}'::text[], 1),
    (v_route, 'Hrad Mirów', 'Romantická zřícenina na skalním hřebeni spojená legendou se sousedními Bobolicemi. Oblíbený fotomotiv Jury.', 50.612, 19.5344, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Mirowie-Castle_in_Mirow_-_panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_w_Mirowie-Castle_in_Mirow_-_panoramio.jpg"}'::text[], 2),
    (v_route, 'Hrad Bobolice', 'Krásně obnovený skalní hrad, jeden z nejfotogeničtějších v Polsku, obzvlášť za soumraku. Přístupný interiér i hradby.', 50.6089, 19.5464, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bobolice_Castle_at_sunset.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bobolice_Castle_at_sunset.jpg"}'::text[], 3),
    (v_route, 'Hrad Ogrodzieniec', 'Největší a nejpůsobivější zřícenina Jury na Podzámčí, kulisa mnoha filmů. Rozlehlý areál na bílých skalách.', 50.4517, 19.5525, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Ogrodzieniec_w_Podzamczu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zamek_Ogrodzieniec_w_Podzamczu.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Kielce – Biskupský palác', 'Renesanční biskupský palác s dochovanými interiéry, dominanta krajského města. Dobrá výchozí zastávka.', 50.8611, 20.6286, 'https://commons.wikimedia.org/wiki/Special:FilePath/20130421_Kielce_Palac_Biskupow_Krakowskich_3127.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/20130421_Kielce_Palac_Biskupow_Krakowskich_3127.jpg"}'::text[], 0),
    (v_route, 'Hrad Chęciny', 'Malebná zřícenina královského hradu na vápencovém hřebeni s vyhlídkovou věží. Daleký rozhled po Svatokřížsku.', 50.7975, 20.4667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C4%99ciny_Castle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C4%99ciny_Castle.jpg"}'::text[], 1),
    (v_route, 'Jeskyně Raj', 'Nádherná krápníková jeskyně s bohatou výzdobou, jedna z nejkrásnějších v Polsku. Příjemné osvěžení za horka.', 50.8203, 20.43, 'https://commons.wikimedia.org/wiki/Special:FilePath/Jaskinia_Raj.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Jaskinia_Raj.jpg"}'::text[], 2),
    (v_route, 'Klášter na Svatém Kříži', 'Benediktinský klášter na druhém nejvyšším vrcholu Svatokřížských hor, nejstarší poutní místo Polska. Symbolický vrchol trasy.', 50.86, 21.05, 'https://commons.wikimedia.org/wiki/Special:FilePath/Swiety_Krzyz_klasztor_3963_20080703.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Swiety_Krzyz_klasztor_3963_20080703.jpg"}'::text[], 3),
    (v_route, 'Kadzielnia', 'Bývalý vápencový lom v Kielcích proměněný v přírodní rezervaci s jezírkem a amfiteátrem. Klidná zastávka na okraji města.', 50.8564, 20.625, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kadzielnia_w_Kielcach.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kadzielnia_w_Kielcach.jpg"}'::text[], 4);
  insert into public.routes
